/* FORGE 14.10 – photorealistic studio movement images, batch 2.
 * Five exercise-specific start/end images. Anatomy derives from existing FORGE artwork.
 * No user data changes and no changes to legacy exercise images.
 * Photos are example poses: always consult written form and safety guidance.
 */
(function(){
 'use strict';
 const photoAssets={"Einarmiges Kurzhantelrudern":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Brustgestütztes Rudern":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Gerade-Arme-Pulldown":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Hammer Curls":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Überkopf-Trizepsstrecken":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
 const names=Object.keys(photoAssets);
 const safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const oldAtlas=window.forgeExerciseIllustrations;
 const oldCatalog=window.forgePublicExercisePictures;
 function card(name){
   const seq=photoAssets[name];if(!seq)return '';
   const captions=['1 · Startposition','2 · Endposition','3 · Beanspruchte Muskeln'];
   return '<div class="forge166-photo-grid" data-forge166-photo="'+safe(name)+'">'+
    seq.map((src,i)=>'<figure class="forge166-photo"><img loading="lazy" decoding="async" src="'+src+'" alt="'+safe(name)+' – '+captions[i]+'"><figcaption>'+captions[i]+'</figcaption></figure>').join('')+
    '</div><p class="forge166-photo-footnote">Die Aufnahmen illustrieren typische Positionen. Achte für die genaue Ausführung auf die Übungsanleitung.</p>';
 }
 window.forgeExerciseIllustrations=function(name){return photoAssets[name]?card(name):(typeof oldAtlas==='function'?oldAtlas(name):'');};
 window.forgePublicExercisePictures=function(name){return photoAssets[name]?card(name):(typeof oldCatalog==='function'?oldCatalog(name):'');};
 function style(){
   if(document.getElementById('forge166PhotoCss'))return;
   const node=document.createElement('style');node.id='forge166PhotoCss';node.textContent=`
     .forge166-photo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0 14px}
     .forge166-photo{margin:0;min-width:0;overflow:hidden;border-radius:11px;background:#16242b;border:1px solid #435650}
     .forge166-photo img{width:100%;height:auto;aspect-ratio:2/2.85;object-fit:cover;display:block;background:#152125}
     .forge166-photo:last-child{grid-column:1/-1}
     .forge166-photo:last-child img{width:100%;max-height:280px;aspect-ratio:1.8/1;object-fit:contain;background:#062128}
     .forge166-photo figcaption{font-size:12px;text-align:center;font-weight:750;color:#e4f0e9;padding:8px 4px 9px}
     .forge166-photo-footnote{font-size:11px!important;color:#b0c2bd!important;line-height:1.45!important;margin:3px 0 12px!important}
     .forge-strength-body:has(.forge166-photo-grid) > .forge159-muscles,
     .forge-strength-body:has(.forge166-photo-grid) > .forge-muscle-map{display:none!important}
     @media(min-width:670px){.forge166-photo-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.forge166-photo:last-child{grid-column:auto}.forge166-photo:last-child img{aspect-ratio:2/2.85;max-height:none}}
   `;document.head.appendChild(node);
 }
 window.forge166BatchInfo={names,card};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',style,{once:true});else style();
})();